import fs from 'node:fs/promises';import assert from 'node:assert/strict';import {captureLongContext} from '../public/pump-turn-long-context-model.js';
const dir='data/research/pump-turn-long-backtest-20261028',cohort=JSON.parse(await fs.readFile(dir+'/cohort.json','utf8')),rows=JSON.parse(await fs.readFile(dir+'/results.json','utf8')),summary=JSON.parse(await fs.readFile(dir+'/summary.json','utf8'));
assert.equal(rows.length,cohort.events.length);const mature=rows.filter(e=>(Math.floor(e.observedAt/60000)+1)*60000+22500000<=cohort.cutoff);assert.equal(mature.length,summary.primary);assert.equal(Object.values(summary.groups).reduce((s,g)=>s+g.all.nAlerts,0),summary.primary);
const cache=new Map();for(const folder of ['data/research/pump-turn-near-eval-20261028/raw',dir+'/raw'])for(const file of await fs.readdir(folder)){const raw=JSON.parse(await fs.readFile(folder+'/'+file,'utf8'));const symbol=decodeURIComponent(file.split('-1m-')[0]),map=cache.get(symbol)??new Map();for(const r of raw){const b=Array.isArray(r)?{t:+r[0],end:+r[6],o:+r[1],h:+r[2],l:+r[3],c:+r[4]}:r;map.set(b.t,b);}cache.set(symbol,map);}
for(const e of mature){assert.equal(captureLongContext(e).label,e.researchClassification.label);const r=e.results.immediate;if(!r.complete)continue;const entryAt=(Math.floor(e.observedAt/60000)+1)*60000,map=cache.get(e.symbol),entry=map.get(entryAt).o;let exit,status;for(let i=0;i<360;i++){const b=map.get(entryAt+i*60000);assert.ok(b);if(b.l<=entry*.94){exit=Math.min(entry*.94,b.o);status='SL';break;}if(b.h>=entry*1.02){exit=entry*1.02;status='TP';break;}if(i===359){exit=b.c;status='TIMEOUT';}}assert.equal(status,r.status);assert.ok(Math.abs(((exit/entry-1)*100-.14)*5-r.netRoe5x)<1e-9);}
const closed=mature.filter(e=>e.results.immediate.complete);assert.equal(closed.length,summary.baseline.n);assert.ok(Math.abs(closed.reduce((s,e)=>s+e.results.immediate.netRoe5x,0)/closed.length-summary.baseline.avgNetRoe5x)<1e-9);
const proof={at:new Date().toISOString(),primary:mature.length,independentPricesAndOutcomesChecked:closed.length,passed:true};await fs.writeFile(dir+'/independent-audit.json',JSON.stringify(proof,null,2));console.log(JSON.stringify(proof));